import{_ as e,c as l,aU as a,a as i}from"./chunks/framework.DIXiA2XH.js";const f=JSON.parse('{"title":"AI相关","description":"","frontmatter":{},"headers":[],"relativePath":"note/ai/ai/index.md","filePath":"note/ai/ai/index.md","lastUpdated":1764682476000}'),o={name:"note/ai/ai/index.md"};function r(d,t,s,n,c,p){return i(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="ai相关" tabindex="-1">AI相关 <a class="header-anchor" href="#ai相关" aria-label="Permalink to &quot;AI相关&quot;">​</a></h1><p>《动手学深度学习》：<a href="https://zh.d2l.ai/" target="_blank" rel="noreferrer">https://zh.d2l.ai/</a></p><h2 id="各大ai云平台" tabindex="-1">各大AI云平台 <a class="header-anchor" href="#各大ai云平台" aria-label="Permalink to &quot;各大AI云平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">云平台</th><th style="text-align:left;">公司</th><th style="text-align:left;">地址</th></tr></thead><tbody><tr><td style="text-align:left;">阿里百炼</td><td style="text-align:left;">阿里巴巴</td><td style="text-align:left;"><a href="https://bailian.console.aliyun.com" target="_blank" rel="noreferrer">https://bailian.console.aliyun.com</a></td></tr><tr><td style="text-align:left;">腾讯T平台</td><td style="text-align:left;">腾讯</td><td style="text-align:left;"><a href="https://cloud.tencent.com/product/ti" target="_blank" rel="noreferrer">https://cloud.tencent.com/product/ti</a></td></tr><tr><td style="text-align:left;">干帆平台</td><td style="text-align:left;">百度</td><td style="text-align:left;"><a href="https://console.bce.baidu.com/qianfan/overview" target="_blank" rel="noreferrer">https://console.bce.baidu.com/qianfan/overview</a></td></tr><tr><td style="text-align:left;">SiliconCloud</td><td style="text-align:left;">硅基流动</td><td style="text-align:left;"><a href="https://siliconflow.cn/zh-cn/siliconcloud" target="_blank" rel="noreferrer">https://siliconflow.cn/zh-cn/siliconcloud</a></td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">火山方舟-火山引擎</td><td style="text-align:left;">字节跳动</td><td style="text-align:left;"><a href="https://www.volcengine.com/product/ark" target="_blank" rel="noreferrer">https://www.volcengine.com/product/ark</a></td></tr></tbody></table><h2 id="相关术语" tabindex="-1">相关术语 <a class="header-anchor" href="#相关术语" aria-label="Permalink to &quot;相关术语&quot;">​</a></h2><h3 id="提示词-rag-微调三者的区别" tabindex="-1">提示词,RAG,微调三者的区别 <a class="header-anchor" href="#提示词-rag-微调三者的区别" aria-label="Permalink to &quot;提示词,RAG,微调三者的区别&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">提示词：</p><p>提示词就是prompt,即我们像大模型输入的提示词，优化prompt的方法就是尽量把提问的<code>背景信息</code>、<code>受众群体</code>、<code>输出格式</code>、<code>语气</code> 等等描述清楚，让大模型更加清晰的理解我们的问题，已给出准确的答案。</p></div><p>举例：比如我们将一篇文章，扔给大模型，告诉他，给我总结下这个文章讲的什么，字数100以内。其实这就是长文本提示词。</p><div class="tip custom-block github-alert"><p class="custom-block-title">RAG：检索增强生成</p><p>RAG就是个人知识库，或者外置数据库，回答的更加精准，避免胡编乱造。</p></div><p>举例：比如你们公司的内部客服培训文档，扔给大模型。</p><p>因为长文本提示词只能对当前会话有效，而且长文本也有一定的限制，你也不可能每次对话都将所有的文章先发过去，再提问，所以RAG技术就出来了， 我们先将知识库上传，大模型会根据提问的问题去找答案。这里面涉及到向量数据库的检索。这样也就避免了每次都需要发送长文本prompt的问题。</p><p>但是RAG也有缺点，需要经常维护知识库，检索速度等</p><div class="tip custom-block github-alert"><p class="custom-block-title">微调：</p><p>就是大模型本身</p></div><p>掌握特定领域的知识范式，通用能力强，消耗的token少，速度快，训练成本高，特定的行业比较适合。</p><p>你可以把他理解成提示词的至尊版，普通的大模型你随便问个东西，他会给你胡编乱造，但是经过微调之后，同样的问题，它会给你非常精准的回答。</p><p>总结：提示词是基础，RAG保证精准度，模型微调保证专业性。</p><div class="tip custom-block github-alert"><p class="custom-block-title">Agent：</p><p></p></div><div class="tip custom-block github-alert"><p class="custom-block-title">Function Call：</p><p></p></div><div class="tip custom-block github-alert"><p class="custom-block-title">MCP：</p><p></p></div>',19)])])}const u=e(o,[["render",r]]);export{f as __pageData,u as default};
